(()=>{const track=document.querySelector('#reference-track');if(!track)return;const controls=document.querySelector('.reference-controls'),prev=controls.querySelector('.reference-prev'),next=controls.querySelector('.reference-next'),label=controls.querySelector('.reference-position'),cards=[...track.children],reduce=matchMedia('(prefers-reduced-motion:reduce)');controls.hidden=false;let queued=false;function step(){return cards.length>1?cards[1].offsetLeft-cards[0].offsetLeft:track.clientWidth}function update(){queued=false;const x=track.scrollLeft,max=Math.max(0,track.scrollWidth-track.clientWidth),first=Math.round(x/step()),visible=Math.max(1,Math.round(track.clientWidth/step()));prev.disabled=x<2;next.disabled=x>=max-2;label.textContent=(visible===1?String(first+1):(first+1)+'–'+Math.min(cards.length,first+visible))+' von '+cards.length+' Projekten'}function move(direction,keyboard=false){track.scrollTo({left:Math.max(0,Math.min(track.scrollWidth-track.clientWidth,track.scrollLeft+direction*step())),behavior:reduce.matches||keyboard?'instant':'smooth'})}prev.addEventListener('click',event=>move(-1,event.detail===0));next.addEventListener('click',event=>move(1,event.detail===0));track.addEventListener('pointerdown',()=>track.scrollTo({left:track.scrollLeft,behavior:'instant'}),{passive:true});track.addEventListener('keydown',event=>{if(event.target!==track)return;if(event.key==='Home'||event.key==='End'){event.preventDefault();track.scrollTo({left:event.key==='Home'?0:track.scrollWidth-track.clientWidth,behavior:'instant'});return;}if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();move(event.key==='ArrowRight'?1:-1,true)}});track.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});new ResizeObserver(update).observe(track);update()})();